WHERE tenant_id=#{__verifiedTenant}
/*appnexus-bind:query.access*/
AND LOCATE(#{query.name},name)>0 AND LOCATE(#{query.code},code)>0
 AND (LOCATE(#{query.keyword},code)>0 OR LOCATE(#{query.keyword},name)>0)
AND draft_archived_at IS NOT NULLNULL


     AND category_id IN (SELECT id FROM selected_categories)
     AND category_id=UUID_TO_BIN(#{query.category})


 AND product_form=#{query.form}
 AND status=#{query.status}
 AND category_config_id=UUID_TO_BIN(#{query.config})

  AND EXISTS(SELECT 1 FROM md_product_v1_attribute_value av

    JOIN md_product_v1_attribute_choice ch ON ch.tenant_id=av.tenant_id AND ch.value_id=av.id

  WHERE av.tenant_id=md_product_v1.tenant_id AND av.product_id=md_product_v1.id AND av.template_item_id=UUID_TO_BIN(#{filter.item})


      AND ch.option_id IN UUID_TO_BIN(#{value})


      AND av.integer_valueav.decimal_valueav.date_valueav.boolean_valueNULL

         = #{filter.values[0]}
         >= #{filter.values[0]}
         <= #{filter.values[0]}
         BETWEEN #{filter.values[0]} AND #{filter.values[1]}
         = NULL


  )
